public int[][] Insert(int[][] ivs, int[] add) {
    var res = new List<int[]>();
    int i = 0, n = ivs.Length, s = add[0], e = add[1];
    while (i < n && ivs[i][1] < s) res.Add(ivs[i++]);   // entirely left: ends before the new one starts
    while (i < n && ivs[i][0] <= e) {                   // overlaps or touches: absorb it
        s = Math.Min(s, ivs[i][0]);
        e = Math.Max(e, ivs[i][1]);
        i++;
    }
    res.Add(new[] { s, e });
    while (i < n) res.Add(ivs[i++]);                    // entirely right
    return res.ToArray();
}
