public int EraseOverlapIntervals(int[][] intervals) {
    Array.Sort(intervals, (a, b) => a[1].CompareTo(b[1]));   // by end
    int removed = 0, end = int.MinValue;
    foreach (var iv in intervals) {
        if (iv[0] >= end) end = iv[1];   // clear of the kept ones: take it, the line moves to its end
        else removed++;                  // starts before the line: remove it
    }
    return removed;
}

