// sounds [start, end): the peak count is how many AudioSources the pool needs
static int PeakVoices(float[] start, float[] end) {
    var s = (float[])start.Clone(); var e = (float[])end.Clone();  // offline analysis: copies are fine
    Array.Sort(s); Array.Sort(e);
    int playing = 0, peak = 0, j = 0;
    for (int i = 0; i < s.Length; i++) {
        while (j < e.Length && e[j] <= s[i]) { j++; playing--; }   // ended by the time s[i] starts
        playing++;
        peak = Math.Max(peak, playing);
    }
    return peak;
}
